--
-- Synced patterns, a pattern category, navigation menus and a classic menu
-- that reference/rest/golden.sh adds for reference/rest/patterns.list over
-- the default install and deletes after with the statements below
-- `-- cleanup`, in mysqldump's form so the tests read them too: a published
-- synced pattern in a category, an unsynced draft pattern by the author, a
-- pattern by the editor whose sync status is not one WordPress takes, a
-- published navigation menu and a draft one by the editor, and a classic
-- menu with a custom link, a link to the sample page under it and a link to
-- a category, links to a post and a taxonomy that are not there and a
-- link to the sample page as a type that is not there;
-- six more links in no menu; the menu is assigned the theme's `primary` location, which no block
-- theme registers, and adds new pages. The navigation menu PHP's fallback
-- creates on php.sh's first page view, dated the day it runs and
-- not in the fixture, is taken out first, and the theme mods that view
-- stores are replaced; db.sh resets the database after.
DELETE FROM wp_posts WHERE ID = 4 AND post_type = 'wp_navigation';
DELETE FROM wp_options WHERE option_name IN ('theme_mods_twentytwentyfive', 'nav_menu_options');
